import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.BwzYn71E.js";const p=JSON.parse('{"title":"Gourmand Requirements Overview — jnk","description":"","frontmatter":{"translationSource":{"title":"老饕需求一览-jnk","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=D6G6MQwnB9jEIcQ0lIsfku","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/gourmand-requirements-overview-jnk"}]]},"headers":[],"relativePath":"gourmand-requirements-overview-jnk.md","filePath":"logistics/src/page-D6G6MQwnB9jEIcQ0lIsfku.md"}'),o={name:"gourmand-requirements-overview-jnk.md"};function s(n,t,i,l,h,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="老饕需求一览-jnk" aria-hidden="true"></span><h1 id="gourmand-requirements-overview-—-jnk" tabindex="-1">Gourmand Requirements Overview — jnk <a class="header-anchor" href="#gourmand-requirements-overview-—-jnk" aria-label="Permalink to &quot;Gourmand Requirements Overview — jnk&quot;">​</a></h1><blockquote><p>Source page ID:<code>D6G6MQwnB9jEIcQ0lIsfku</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=D6G6MQwnB9jEIcQ0lIsfku" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-NrEhNYNnxNPH2PNBjYg2IQ"></span></p><span class="logistics-source-anchor" id="客栈老饕需求一览" aria-hidden="true"></span><h2 id="inn-gourmand-requirements-overview" tabindex="-1">Inn Gourmand Requirements Overview <a class="header-anchor" href="#inn-gourmand-requirements-overview" aria-label="Permalink to &quot;Inn Gourmand Requirements Overview&quot;">​</a></h2><blockquote><p>This file was organized by AI using the data tables in akedata, as a reference when looking up dishes.</p></blockquote><p><span id="source-block-fM5MrXVZ6uIjgjeH1viPFK"></span></p><span class="logistics-source-anchor" id="怎么读" aria-hidden="true"></span><h3 id="how-to-read-this-guide" tabindex="-1">How to Read This Guide <a class="header-anchor" href="#how-to-read-this-guide" aria-label="Permalink to &quot;How to Read This Guide&quot;">​</a></h3><p>Each gourmand has two levels of requirements:</p><ol><li><p><strong>Guest-level requirement</strong> — if at least one dish on the menu meets it, this guest <strong>may appear</strong>;</p></li><li><p><strong>Specific requests</strong> — when the guest actually orders, one of these is <strong>chosen at random</strong>, and it may be precisely the one you cannot make.</p></li></ol><p>The more guest types your menu covers, and the more requests you can fulfill within each type, the better your chances of satisfying them.</p><p>Symbols used in the conditions:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td>+</td><td>The <strong>same dish</strong> must meet both conditions (e.g. soup + contains Fin Fillet [A])</td></tr><tr><td>AND</td><td><strong>All</strong> conditions must be met</td></tr><tr><td>OR</td><td>Meet <strong>any one</strong> of the conditions (usually regular/premium ingredient grades)</td></tr><tr><td>not</td><td>Must <strong>not</strong> contain / must not be</td></tr><tr><td>(beverage)</td><td>This request is for a beverage, not a food dish</td></tr></tbody></table><hr><p><span id="source-block-m5bg0gq4LVwbsmLJOl8236"></span></p><span class="logistics-source-anchor" id="一、普通老饕-7-种" aria-hidden="true"></span><h3 id="_1-regular-gourmands-7-types" tabindex="-1">1. Regular Gourmands (7 Types) <a class="header-anchor" href="#_1-regular-gourmands-7-types" aria-label="Permalink to &quot;1. Regular Gourmands (7 Types)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Type</th><th>Guest-Level Requirement</th><th>Possible Requests</th></tr></thead><tbody><tr><td>1</td><td>Male Farmer</td><td>contains Flour</td><td>6</td></tr><tr><td>2</td><td>Female Farmer</td><td>(contains Fin Fillet) OR (contains Fin Fillet [A])</td><td>6</td></tr><tr><td>3</td><td>Brawny Worker</td><td>(nourishing) OR (soup)</td><td>6</td></tr><tr><td>4</td><td>Female Worker</td><td>(visually appealing) OR (dessert)</td><td>6</td></tr><tr><td>5</td><td>Male Worker</td><td>(contains Meat) OR (contains Meat [A])</td><td>8</td></tr><tr><td>6</td><td>Schoolboy</td><td>dish</td><td>4</td></tr><tr><td>7</td><td>Schoolgirl</td><td>dessert</td><td>4</td></tr></tbody></table><p><span id="source-block-QpOM2ta9jkiIDP0IoTJ1YT"></span></p><span class="logistics-source-anchor" id="普1-·-男农夫" aria-hidden="true"></span><h4 id="n1-·-male-farmer" tabindex="-1">N1 · Male Farmer <a class="header-anchor" href="#n1-·-male-farmer" aria-label="Permalink to &quot;N1 · Male Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: contains Flour</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Some flour-based food, with plenty of salt. I like strong flavors.”</td><td>salty + contains Flour</td></tr><tr><td>2</td><td>“Any flour-based food without that fishy fin smell?”</td><td>(contains Flour) AND (not umami)</td></tr><tr><td>3</td><td>“Let me think... a stir-fried dish, as spicy as possible.”</td><td>spicy + dish</td></tr><tr><td>4</td><td>“Salty or spicy, either is fine. Just bring something tasty.”</td><td>(salty) OR (spicy)</td></tr><tr><td>5</td><td>“My teeth have been aching lately, so nothing sour.”</td><td>not sour</td></tr><tr><td>6</td><td>“A dessert that is not too sweet. I am cutting body fat.”</td><td>(dessert) AND (not sweet)</td></tr></tbody></table><p><span id="source-block-H3Wcyes826e5qjy8LQwHpb"></span></p><span class="logistics-source-anchor" id="普2-·-女农夫" aria-hidden="true"></span><h4 id="n2-·-female-farmer" tabindex="-1">N2 · Female Farmer <a class="header-anchor" href="#n2-·-female-farmer" aria-label="Permalink to &quot;N2 · Female Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (contains Fin Fillet) OR (contains Fin Fillet [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Fins really are best eaten fresh...”</td><td>(umami + contains Fin Fillet) OR (umami + contains Fin Fillet [A])</td></tr><tr><td>2</td><td>“Do you have &quot;fins swimming in water&quot;? I mean fin soup.”</td><td>soup + contains Fin Fillet [A]</td></tr><tr><td>3</td><td>“I feel like seafood... would that be too much trouble?”</td><td>seafood</td></tr><tr><td>4</td><td>“A dish full of wok flavor. Oh, absolutely no spice.”</td><td>(dish) AND (not spicy)</td></tr><tr><td>5</td><td>“Anything sweet and sour, like fruit juice?”</td><td>fruit aroma(beverage)</td></tr><tr><td>6</td><td>“Another drink, but no tea. It keeps me awake.”</td><td>not tea aroma(beverage)</td></tr></tbody></table><p><span id="source-block-NvstCkNHmqZdz4UIlDGDgI"></span></p><span class="logistics-source-anchor" id="普3-·-壮汉工人" aria-hidden="true"></span><h4 id="n3-·-brawny-worker" tabindex="-1">N3 · Brawny Worker <a class="header-anchor" href="#n3-·-brawny-worker" aria-label="Permalink to &quot;N3 · Brawny Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (nourishing) OR (soup)</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“A soup, something light.”</td><td>(soup) AND (not spicy) AND (not salty)</td></tr><tr><td>2</td><td>“One vegetable dish.”</td><td>vegetarian + dish</td></tr><tr><td>3</td><td>“A wholesome meal to nourish body and mind, please.”</td><td>nourishing</td></tr><tr><td>4</td><td>“Do you have a refreshing soup without oil?”</td><td>(soup) AND (does not contain Seed Oil)</td></tr><tr><td>5</td><td>“A cup of fine tea.”</td><td>tea aroma(beverage)</td></tr><tr><td>6</td><td>“A drink, and remember: I do not touch alcohol.”</td><td>not alcohol aroma(beverage)</td></tr></tbody></table><p><span id="source-block-NGQDPXOMc4Pl6QVJms6wQL"></span></p><span class="logistics-source-anchor" id="普4-·-女工人" aria-hidden="true"></span><h4 id="n4-·-female-worker" tabindex="-1">N4 · Female Worker <a class="header-anchor" href="#n4-·-female-worker" aria-label="Permalink to &quot;N4 · Female Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (visually appealing) OR (dessert)</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Any pretty dishes that will look good in photos?”</td><td>visually appealing</td></tr><tr><td>2</td><td>“Hmm... I want dessert, preferably a little sour.”</td><td>(dessert) AND (sour)</td></tr><tr><td>3</td><td>“...Some dessert, but no flour, please.”</td><td>(dessert) AND (does not contain Flour)</td></tr><tr><td>4</td><td>“I want something elegant... a dish with a story.”</td><td>elegant</td></tr><tr><td>5</td><td>“Some soup without seafood.”</td><td>(soup) AND (not seafood)</td></tr><tr><td>6</td><td>“Umami brings a fishy smell. Anything without that is fine.”</td><td>not umami</td></tr></tbody></table><p><span id="source-block-9dixN2BUnMnVRaEpcPb5ex"></span></p><span class="logistics-source-anchor" id="普5-·-男工人" aria-hidden="true"></span><h4 id="n5-·-male-worker" tabindex="-1">N5 · Male Worker <a class="header-anchor" href="#n5-·-male-worker" aria-label="Permalink to &quot;N5 · Male Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (contains Meat) OR (contains Meat [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Carbs! Meat! Pile them on!”</td><td>(staple + contains Meat) OR (staple + contains Meat [A])</td></tr><tr><td>2</td><td>“Top-quality meat! Make it into a dish!”</td><td>dish + contains Meat [A]</td></tr><tr><td>3</td><td>“Some sour soup to help digestion.”</td><td>sour + soup</td></tr><tr><td>4</td><td>“A dessert, something as sour as plums!”</td><td>sour + dessert</td></tr><tr><td>5</td><td>“Bring anything, as long as it is not one of those nourishing medicinal meals!”</td><td>not nourishing</td></tr><tr><td>6</td><td>“Meat! Bring meat! Nothing purely vegetarian!”</td><td>(meat-based) AND (not vegetarian)</td></tr><tr><td>7</td><td>“Come on, bring the liquor in big bowls!”</td><td>alcohol aroma(beverage)</td></tr><tr><td>8</td><td>“Something to drink and clear my palate, as long as it is not milky.”</td><td>not milk aroma(beverage)</td></tr></tbody></table><p><span id="source-block-qrrxzQHjF3kEqy4N50Sb2P"></span></p><span class="logistics-source-anchor" id="普6-·-男孩学生" aria-hidden="true"></span><h4 id="n6-·-schoolboy" tabindex="-1">N6 · Schoolboy <a class="header-anchor" href="#n6-·-schoolboy" aria-label="Permalink to &quot;N6 · Schoolboy&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: dish</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Bring me a dish.”</td><td>dish</td></tr><tr><td>2</td><td>“Bring me a dish made with Matoberry.”</td><td>dish + contains Matoberry</td></tr><tr><td>3</td><td>“Anything will do, but nothing made with rice.”</td><td>does not contain Amber Rice</td></tr><tr><td>4</td><td>“Anything will do, but no dessert.”</td><td>not dessert</td></tr></tbody></table><p><span id="source-block-vHONVVIIKSSekdQQd4D2qm"></span></p><span class="logistics-source-anchor" id="普7-·-女孩学生" aria-hidden="true"></span><h4 id="n7-·-schoolgirl" tabindex="-1">N7 · Schoolgirl <a class="header-anchor" href="#n7-·-schoolgirl" aria-label="Permalink to &quot;N7 · Schoolgirl&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: dessert</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Dessert, please.”</td><td>dessert</td></tr><tr><td>2</td><td>“Dessert, please, without Sugar.”</td><td>(dessert) AND (does not contain Sugar)</td></tr><tr><td>3</td><td>“Dessert, please, without Starch.”</td><td>(dessert) AND (does not contain Starch)</td></tr><tr><td>4</td><td>“Please bring me anything, as long as it is not a staple.”</td><td>not staple</td></tr></tbody></table><hr><p><span id="source-block-WtNcLNlYpWwgKCI536SBqT"></span></p><span class="logistics-source-anchor" id="二、特殊客-15-种" aria-hidden="true"></span><h3 id="_2-special-guests-15-types" tabindex="-1">2. Special Guests (15 Types) <a class="header-anchor" href="#_2-special-guests-15-types" aria-label="Permalink to &quot;2. Special Guests (15 Types)&quot;">​</a></h3><p>These guests appear during the event. Eligibility likewise depends only on the guest-level requirement; after they arrive, one of their possible requests is chosen at random.</p><p>(Some character descriptions overlap with regular gourmands: for example, both categories include a Brawny Worker. Distinguish them by N/S + number.)</p><table tabindex="0"><thead><tr><th>#</th><th>Type</th><th>Guest-Level Requirement</th><th>Possible Requests</th></tr></thead><tbody><tr><td>1</td><td>Brawny Worker</td><td>staple</td><td>5</td></tr><tr><td>2</td><td>Heavyset Male Teacher</td><td>dish</td><td>5</td></tr><tr><td>3</td><td>Child Farmer</td><td>dessert</td><td>5</td></tr><tr><td>4</td><td>Elderly Farmer</td><td>soup</td><td>5</td></tr><tr><td>5</td><td>Schoolboy</td><td>umami</td><td>5</td></tr><tr><td>6</td><td>Male Farmer</td><td>salty</td><td>5</td></tr><tr><td>7</td><td>Boy Engineer</td><td>spicy</td><td>5</td></tr><tr><td>8</td><td>Child Farmer (Girl)</td><td>sweet</td><td>5</td></tr><tr><td>9</td><td>Male Engineer</td><td>sour</td><td>5</td></tr><tr><td>10</td><td>Male Worker</td><td>(meat-based) OR (contains Meat) OR (contains Meat [A])</td><td>5</td></tr><tr><td>11</td><td>Schoolgirl</td><td>(vegetarian) OR (contains Relishroom) OR (contains Relishroom [A])</td><td>5</td></tr><tr><td>12</td><td>Female Farmer</td><td>(seafood) OR (contains Fin Fillet) OR (contains Fin Fillet [A])</td><td>5</td></tr><tr><td>13</td><td>Girl Engineer</td><td>(nourishing) OR (contains Sourberry) OR (contains Sourberry [A])</td><td>5</td></tr><tr><td>14</td><td>Female Worker</td><td>(visually appealing) OR (contains Spice Mix 130)</td><td>4</td></tr><tr><td>15</td><td>Female Teacher</td><td>(elegant) OR (contains Ballpea)</td><td>4</td></tr></tbody></table><p><span id="source-block-3dqldgoluj6m22d5CTYGeF"></span></p><span class="logistics-source-anchor" id="特1-·-壮汉工人" aria-hidden="true"></span><h4 id="s1-·-brawny-worker" tabindex="-1">S1 · Brawny Worker <a class="header-anchor" href="#s1-·-brawny-worker" aria-label="Permalink to &quot;S1 · Brawny Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: staple</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Time to carb up. I mean rice.”</td><td>staple + contains Amber Rice</td></tr><tr><td>2</td><td>“Some carbs, something nice and salty.”</td><td>salty + staple</td></tr><tr><td>3</td><td>“Carbs, carbs. Something rich in umami.”</td><td>umami + staple</td></tr><tr><td>4</td><td>“Filling carbs, but nothing spicy.”</td><td>(staple) AND (not spicy)</td></tr><tr><td>5</td><td>“I want filling carbs without any fancy frills!”</td><td>(staple) AND (not visually appealing) AND (not elegant)</td></tr></tbody></table><p><span id="source-block-mQckZVzPOAceawOVra5kMT"></span></p><span class="logistics-source-anchor" id="特2-·-胖男教师" aria-hidden="true"></span><h4 id="s2-·-heavyset-male-teacher" tabindex="-1">S2 · Heavyset Male Teacher <a class="header-anchor" href="#s2-·-heavyset-male-teacher" aria-label="Permalink to &quot;S2 · Heavyset Male Teacher&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: dish</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“The beauty of a meal is that no feast is complete without fins.”</td><td>(dish + contains Fin Fillet) OR (dish + contains Fin Fillet [A])</td></tr><tr><td>2</td><td>“The wonder of a dish lies in keeping mushrooms well away.”</td><td>(dish) AND (does not contain Relishroom) AND (does not contain Relishroom [A])</td></tr><tr><td>3</td><td>“The etiquette of a meal lies in whetting the appetite with sourness.”</td><td>sour + dish</td></tr><tr><td>4</td><td>“The courage of a dish lies in the art of spice.”</td><td>spicy + dish</td></tr><tr><td>5</td><td>“The wisdom of a dish lies in avoiding cloying sweetness.”</td><td>(dish) AND (not sweet)</td></tr></tbody></table><p><span id="source-block-pqWofnulCWRAzBh8Kwwfz8"></span></p><span class="logistics-source-anchor" id="特3-·-孩童农夫" aria-hidden="true"></span><h4 id="s3-·-child-farmer" tabindex="-1">S3 · Child Farmer <a class="header-anchor" href="#s3-·-child-farmer" aria-label="Permalink to &quot;S3 · Child Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: dessert</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“You know, sweet pastries with a milky aroma.”</td><td>(dessert + contains Milk) OR (dessert + contains Milk [A])</td></tr><tr><td>2</td><td>“You know, sweet pastries with an eggy aroma.”</td><td>(dessert + contains Egg) OR (dessert + contains Egg [A])</td></tr><tr><td>3</td><td>“You know, pastries that will not give me cavities.”</td><td>(dessert) AND (does not contain Sugar)</td></tr><tr><td>4</td><td>“You know, delicious salty pastries.”</td><td>salty + dessert</td></tr><tr><td>5</td><td>“Those sweet-and-sour pastries for afternoon tea.”</td><td>(sour + dessert) OR (sweet + dessert)</td></tr></tbody></table><p><span id="source-block-8rJ1TtBTx6OVmqiD6ZAEX3"></span></p><span class="logistics-source-anchor" id="特4-·-老者农夫" aria-hidden="true"></span><h4 id="s4-·-elderly-farmer" tabindex="-1">S4 · Elderly Farmer <a class="header-anchor" href="#s4-·-elderly-farmer" aria-label="Permalink to &quot;S4 · Elderly Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: soup</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Any fine soup? Leave out the Ballpeas.”</td><td>(soup) AND (does not contain Ballpea)</td></tr><tr><td>2</td><td>“Any fine soup? Elegance comes first.”</td><td>elegant + soup</td></tr><tr><td>3</td><td>“Any fine soup? It needs sourness to cut the richness.”</td><td>sour + soup</td></tr><tr><td>4</td><td>“Any fine soup? Umami comes first.”</td><td>umami + soup</td></tr><tr><td>5</td><td>“Any fine soup? Nothing purely vegetarian.”</td><td>(soup) AND (not vegetarian)</td></tr></tbody></table><p><span id="source-block-q2LVPeqjZ8haGqTSrFrWK8"></span></p><span class="logistics-source-anchor" id="特5-·-男孩学生" aria-hidden="true"></span><h4 id="s5-·-schoolboy" tabindex="-1">S5 · Schoolboy <a class="header-anchor" href="#s5-·-schoolboy" aria-label="Permalink to &quot;S5 · Schoolboy&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: umami</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Umami comes first in every meal; I just do not like fins.”</td><td>(umami) AND (does not contain Fin Fillet) AND (does not contain Fin Fillet [A])</td></tr><tr><td>2</td><td>“Umami comes first in every meal; nourishment gives the flavor depth.”</td><td>(umami) AND (nourishing)</td></tr><tr><td>3</td><td>“Umami comes first in every meal, but soup is second-rate.”</td><td>(umami) AND (not soup)</td></tr><tr><td>4</td><td>“Some drinks, but no tea.”</td><td>not tea aroma(beverage)</td></tr><tr><td>5</td><td>“Some drinks, preferably fruity.”</td><td>fruit aroma(beverage)</td></tr></tbody></table><p><span id="source-block-AeVb45KJ7TGtlWTAkO51xU"></span></p><span class="logistics-source-anchor" id="特6-·-男农夫" aria-hidden="true"></span><h4 id="s6-·-male-farmer" tabindex="-1">S6 · Male Farmer <a class="header-anchor" href="#s6-·-male-farmer" aria-label="Permalink to &quot;S6 · Male Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: salty</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Anything salty will do, but no soup.”</td><td>(salty) AND (not soup)</td></tr><tr><td>2</td><td>“Anything will do, with more salt, but no meat.”</td><td>(salty) AND (does not contain Meat) AND (does not contain Meat [A])</td></tr><tr><td>3</td><td>“Something with less oil, but plenty of salt.”</td><td>(salty) AND (does not contain Seed Oil)</td></tr><tr><td>4</td><td>“Any drink, as long as it is not fruity.”</td><td>not fruit aroma(beverage)</td></tr><tr><td>5</td><td>“Any drink will do, but it must refresh my palate and cut the richness.”</td><td>tea aroma + beverage(beverage)</td></tr></tbody></table><p><span id="source-block-nbMFYutWTrIXm9qjREGSPn"></span></p><span class="logistics-source-anchor" id="特7-·-男孩工程师" aria-hidden="true"></span><h4 id="s7-·-boy-engineer" tabindex="-1">S7 · Boy Engineer <a class="header-anchor" href="#s7-·-boy-engineer" aria-label="Permalink to &quot;S7 · Boy Engineer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: spicy</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Anything! Lots of spice! No staples!”</td><td>(spicy) AND (not staple)</td></tr><tr><td>2</td><td>“Something to eat, very spicy but not sour enough to hurt my teeth.”</td><td>(spicy) AND (not sour)</td></tr><tr><td>3</td><td>“The meat must be top-quality, and spicy. Very spicy!”</td><td>spicy + contains Meat [A]</td></tr><tr><td>4</td><td>“A drink! Anything! But it must not get me drunk!”</td><td>not alcohol aroma(beverage)</td></tr><tr><td>5</td><td>“A drink, but without that grassy-leaf flavor!”</td><td>not tea aroma(beverage)</td></tr></tbody></table><p><span id="source-block-STf7YBFXaHs0lsXHBMNgxi"></span></p><span class="logistics-source-anchor" id="特8-·-孩童农夫-女" aria-hidden="true"></span><h4 id="s8-·-child-farmer-girl" tabindex="-1">S8 · Child Farmer (Girl) <a class="header-anchor" href="#s8-·-child-farmer-girl" aria-label="Permalink to &quot;S8 · Child Farmer (Girl)&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: sweet</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Might I have something sweet and fruity?”</td><td>(sweet + contains Sourberry) OR (sweet + contains Sourberry [A])</td></tr><tr><td>2</td><td>“Might I have something sweet without meat?”</td><td>(sweet) AND (does not contain Meat) AND (does not contain Meat [A])</td></tr><tr><td>3</td><td>“Might I have something sweet that is not a pastry?”</td><td>(sweet) AND NOT (sweet + dessert)</td></tr><tr><td>4</td><td>“Might I have a drink that is not spicy?”</td><td>not alcohol aroma(beverage)</td></tr><tr><td>5</td><td>“Might I have a milk drink?”</td><td>milk aroma(beverage)</td></tr></tbody></table><p><span id="source-block-B8fB1eX777xO23WFVqCsYH"></span></p><span class="logistics-source-anchor" id="特9-·-男工程师" aria-hidden="true"></span><h4 id="s9-·-male-engineer" tabindex="-1">S9 · Male Engineer <a class="header-anchor" href="#s9-·-male-engineer" aria-label="Permalink to &quot;S9 · Male Engineer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: sour</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“I think... a Matoberry dish, with sourness to bring out the flavor.”</td><td>sour + contains Matoberry</td></tr><tr><td>2</td><td>“Hmm... a fin dish, with sourness to cut the richness.”</td><td>(sour + contains Fin Fillet) OR (sour + contains Fin Fillet [A])</td></tr><tr><td>3</td><td>“I think... a sour dish, but not a dessert.”</td><td>(sour) AND (not dessert)</td></tr><tr><td>4</td><td>“Perhaps... any drink? But I am lactose intolerant.”</td><td>not milk aroma(beverage)</td></tr><tr><td>5</td><td>“Yes... a few drinks are in order.”</td><td>alcohol aroma(beverage)</td></tr></tbody></table><p><span id="source-block-5GaBJkidjv86lgzE89bcc0"></span></p><span class="logistics-source-anchor" id="特10-·-男工人" aria-hidden="true"></span><h4 id="s10-·-male-worker" tabindex="-1">S10 · Male Worker <a class="header-anchor" href="#s10-·-male-worker" aria-label="Permalink to &quot;S10 · Male Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (meat-based) OR (contains Meat) OR (contains Meat [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Meat.”</td><td>meat-based</td></tr><tr><td>2</td><td>“Good meat. No soup.”</td><td>(contains Meat [A]) AND (not soup)</td></tr><tr><td>3</td><td>“Meat. A dish.”</td><td>(dish + contains Meat) OR (dish + contains Meat [A])</td></tr><tr><td>4</td><td>“Drink. Tea.”</td><td>tea aroma(beverage)</td></tr><tr><td>5</td><td>“Drink. No fruit flavor.”</td><td>not fruit aroma(beverage)</td></tr></tbody></table><p><span id="source-block-jMMXNZuIW3sID3eH221MXW"></span></p><span class="logistics-source-anchor" id="特11-·-女孩学生" aria-hidden="true"></span><h4 id="s11-·-schoolgirl" tabindex="-1">S11 · Schoolgirl <a class="header-anchor" href="#s11-·-schoolgirl" aria-label="Permalink to &quot;S11 · Schoolgirl&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (vegetarian) OR (contains Relishroom) OR (contains Relishroom [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Hey, do you have anything vegetarian?”</td><td>vegetarian</td></tr><tr><td>2</td><td>“Hey, do you have any Relishroom soup?”</td><td>soup + contains Relishroom [A]</td></tr><tr><td>3</td><td>“Hey, do you have any Relishroom dishes?”</td><td>dish + contains Relishroom [A]</td></tr><tr><td>4</td><td>“Hey, do you have any nonalcoholic drinks?”</td><td>not alcohol aroma(beverage)</td></tr><tr><td>5</td><td>“Hey, do you have any classic, refreshing drinks?”</td><td>tea aroma(beverage)</td></tr></tbody></table><p><span id="source-block-YE5g8DTon9ftncAlrMJG6v"></span></p><span class="logistics-source-anchor" id="特12-·-女农夫" aria-hidden="true"></span><h4 id="s12-·-female-farmer" tabindex="-1">S12 · Female Farmer <a class="header-anchor" href="#s12-·-female-farmer" aria-label="Permalink to &quot;S12 · Female Farmer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (seafood) OR (contains Fin Fillet) OR (contains Fin Fillet [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“A fine season! Time to eat something from the water!”</td><td>seafood</td></tr><tr><td>2</td><td>“Top-quality seafood! Do not make it into soup!”</td><td>(contains Fin Fillet [A]) AND (not soup)</td></tr><tr><td>3</td><td>“A fin dish! Make it a staple!”</td><td>(staple + contains Fin Fillet) OR (staple + contains Fin Fillet [A])</td></tr><tr><td>4</td><td>“Something to drink, without that milky smell.”</td><td>not milk aroma(beverage)</td></tr><tr><td>5</td><td>“Some drinks with the meal, but nothing that goes to my head.”</td><td>not alcohol aroma(beverage)</td></tr></tbody></table><p><span id="source-block-wTliPiHptJ0v6GbSxILQTo"></span></p><span class="logistics-source-anchor" id="特13-·-女孩工程师" aria-hidden="true"></span><h4 id="s13-·-girl-engineer" tabindex="-1">S13 · Girl Engineer <a class="header-anchor" href="#s13-·-girl-engineer" aria-label="Permalink to &quot;S13 · Girl Engineer&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (nourishing) OR (contains Sourberry) OR (contains Sourberry [A])</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“Food ought to be nourishing.”</td><td>nourishing</td></tr><tr><td>2</td><td>“Premium Sourberries really do not belong in a staple.”</td><td>(contains Sourberry [A]) AND (not staple)</td></tr><tr><td>3</td><td>“Premium Sourberries really should be made into dessert.”</td><td>dessert + contains Sourberry [A]</td></tr><tr><td>4</td><td>“A drink really ought to have Sourberries in it.”</td><td>fruit aroma(beverage)</td></tr><tr><td>5</td><td>“No Sourberries this time. Some milk instead.”</td><td>milk aroma(beverage)</td></tr></tbody></table><p><span id="source-block-7dVXOhbqVbR7wIOjB2uerD"></span></p><span class="logistics-source-anchor" id="特14-·-女工人" aria-hidden="true"></span><h4 id="s14-·-female-worker" tabindex="-1">S14 · Female Worker <a class="header-anchor" href="#s14-·-female-worker" aria-label="Permalink to &quot;S14 · Female Worker&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (visually appealing) OR (contains Spice Mix 130)</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“As long as it is not ugly. Looking good matters most.”</td><td>visually appealing</td></tr><tr><td>2</td><td>“Let me see what Spice Mix 130 can do.”</td><td>contains Spice Mix 130</td></tr><tr><td>3</td><td>“Dishes are all ugly. Bring something pretty.”</td><td>(visually appealing) AND (not dish)</td></tr><tr><td>4</td><td>“The drinks are all quite good. Something fruity or milky, then.”</td><td>(fruit aroma) OR (milk aroma)(beverage)</td></tr></tbody></table><p><span id="source-block-qjvBtFhmXvU8FyZdSM7x7h"></span></p><span class="logistics-source-anchor" id="特15-·-女教师" aria-hidden="true"></span><h4 id="s15-·-female-teacher" tabindex="-1">S15 · Female Teacher <a class="header-anchor" href="#s15-·-female-teacher" aria-label="Permalink to &quot;S15 · Female Teacher&quot;">​</a></h4><p><strong>Guest-level requirement</strong>: (elegant) OR (contains Ballpea)</p><p><strong>Possible requests</strong> (chosen at random):</p><table tabindex="0"><thead><tr><th>#</th><th>Utterance</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td>“When dining, elegance ought to come first.”</td><td>elegant</td></tr><tr><td>2</td><td>“When savoring soup, one ought to make good use of Ballpeas.”</td><td>soup + contains Ballpea</td></tr><tr><td>3</td><td>“A skilled cook of Ballpeas ought to forgo cloying sweetness.”</td><td>(contains Ballpea) AND (does not contain Sugar)</td></tr><tr><td>4</td><td>“For those who enjoy a drink, tea and liquor ought to come first.”</td><td>(tea aroma) OR (alcohol aroma)(beverage)</td></tr></tbody></table></div>',1)])])}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
